input.find:
for _, char := range letters {
	if char == '.' || char == '*' {
		patterns = append(patterns, fmt.Sprintf("\\%c+", char))
	} else {
		patterns = append(patterns, fmt.Sprintf("%c+", char))
	}
}

input.replace:
for _, char := range letters {
	if char == '.' || char == '*' {
		patterns = append(patterns, fmt.Sprintf("\\%c+", char))
	} else if char >= 'a' && char <= 'z' {
		patterns = append(patterns, fmt.Sprintf("%c+", char))
	}
}
